import React, { useState } from "react";
import axios from "axios";
import { LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid } from "recharts";

function Dashboard(){

  const [file, setFile] = useState(null);
  const [data, setData] = useState(null);

  const uploadFile = async () => {

    const formData = new FormData();
    formData.append("file", file);

    const res = await axios.post(
      "http://127.0.0.1:8000/upload",
      formData
    );

    setData(res.data);
  };

  return(
    <div style={{padding:"20px"}}>

      <input type="file" onChange={e => setFile(e.target.files[0])} />
      <button onClick={uploadFile}>Analyze</button>

      {data && (
        <>
          <h2>Health Score: {data.summary.health_score}</h2>

          <p>Profit Margin: {data.summary.profit_margin}%</p>

          <h3>Revenue Forecast</h3>

          <LineChart width={400} height={250} data={
            data.forecast.map((v,i)=>({month:i+1, revenue:v}))
          }>
            <XAxis dataKey="month" />
            <YAxis />
            <Tooltip />
            <CartesianGrid />
            <Line dataKey="revenue" />
          </LineChart>

          <h3>Risks</h3>
          <ul>
            {data.summary.risks.length === 0 ? 
              <li>No major risks</li> :
              data.summary.risks.map((r,i)=><li key={i}>{r}</li>)
            }
          </ul>

          <h3>AI Insights</h3>
          <pre>{data.ai_insights}</pre>
        </>
      )}

    </div>
  )
}

export default Dashboard;
